import React, { useEffect, useState } from "react";
import axios from "axios";
import "../Styles/MyApplications.css";

const MyApplications = () => {
  // Store user's job applications
  const [applications, setApplications] = useState([]);

  // Fetch applications from MongoDB for the logged-in student
  useEffect(() => {
    const fetchApplications = async () => {
      try {
        const loggedUser = JSON.parse(localStorage.getItem("loggedUser"));
        if (!loggedUser) {
          alert("Please login first!");
          return;
        }

        const res = await axios.get(
          `http://localhost:3001/applications/${loggedUser.email}`
        );
        setApplications(res.data);
      } catch (err) {
        console.error(err);
        alert("Failed to load applications from database.");
      }
    };

    fetchApplications();
  }, []);

  // Cancel application → delete from MongoDB and update UI
  const handleCancel = async (id) => {
    try {
      await axios.delete(`http://localhost:3001/applications/${id}`);
      setApplications(applications.filter((app) => app._id !== id));
      alert("Application canceled successfully.");
    } catch (err) {
      console.error(err);
      alert("Error canceling application.");
    }
  };

  return (
    <div className="applications-page">
      <h1 className="applications-title">
        My <span className="accent">Applications</span>
      </h1>
      <p className="applications-sub">
        Track and manage your submitted job applications.
      </p>

      {/* Display list of applications */}
      <div className="applications-list">
        {applications.length === 0 ? (
          <p>No applications found.</p>
        ) : (
          applications.map((app) => (
            <div className="application-card" key={app._id}>
              <div className="app-info">
                <div className="app-icon">🏢</div>
                <div>
                  <h3 className="job-title">{app.jobTitle}</h3>
                  <p className="company">Company: {app.organization}</p>
                  <p className="details">
                    Applied on:{" "}
                    {new Date(app.appliedAt).toLocaleDateString("en-GB")}
                  </p>
                </div>
              </div>

              <div className="app-actions">
                <button
                  className="withdraw-btn"
                  onClick={() => handleCancel(app._id)}
                >
                  Cancel Application
                </button>
                <button className="status-btn">
                  {app.status || "Pending Review"}
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default MyApplications;
